(* [comment removed for export] *)
Lemma AStreamSvc_fs_retire : forall LF k ff fp m0 m1 m2 LB v S implb,
  as_RFS H LF m0 -> fresh_frame H LF k ff fp -> AStreamSvc LB m1 v S implb -> fsobj H LF v NEWSZ_SSVC ->
  munch [(ff, ff + 8); (sh ff, sh ff + fshn k); (fp, fp + 1)]%Z m1 m2 -> wmono bsegs m1 m2 -> AStreamSvc LB m2 v S implb.
Proof.
  intros LF k ff fp m0 m1 m2 LB v S implb RF FF SV FO MU WM.
  pose proof (ff_facts H LF k ff fp FF) as (K0 & _). pose proof aceil_facts as (AF & _).
  pose proof SV as (p & j7 & _ & _ & _ & _ & RB & _). pose proof (rblock_bounds _ _ RB) as (B1 & B2 & B3 & B4 & B5 & B6). pose proof RB as (_ & _ & _ & AP & _).
  eapply AStreamSvc_transport; [exact SV| exact MU| exact WM| |].
  - apply (disjoint_fsW5_retire H aceil aceil); [lia|]. eapply (fsobj_disjoint H HH); [exact RF| exact FO| exact FF| exact B1| exact B2| exact B3| exact AP| left; lia].
  - apply (disjoint_fsW5_retire H aceil aceil); [lia|]. eapply (fsobj_disjoint_sh H HH); [exact RF| exact FO| exact FF| exact B1| exact B2| exact B3| lia].
Qed.

Lemma AImplBlockC_fs_retire : forall LF k ff fp m0 m1 m2 LB b I,
  as_RFS H LF m0 -> fresh_frame H LF k ff fp -> AImplBlockC LB m1 b I -> fsobj H LF b SZ_SPCI_IMPL ->
  (0 < im_vcap I -> fsobj H LF (im_vb I) (8 * im_vcap I)) ->
  munch [(ff, ff + 8); (sh ff, sh ff + fshn k); (fp, fp + 1)]%Z m1 m2 -> wmono bsegs m1 m2 -> AImplBlockC LB m2 b I.
Proof.
  intros LF k ff fp m0 m1 m2 LB b I RF FF IB FO FOV MU WM.
  pose proof (ff_facts H LF k ff fp FF) as (K0 & _). pose proof aceil_facts as (AF & _).
  pose proof IB as (p & j7 & _ & RB & _ & _ & _ & _ & _ & _ & VST & _). pose proof (rblock_bounds _ _ RB) as (B1 & B2 & B3 & B4 & B5 & B6). pose proof RB as (_ & _ & _ & AP & _).
  eapply AImplBlockC_transport; [exact IB| exact MU| exact WM| | | |].
  - apply (disjoint_fsW5_retire H aceil aceil); [lia|]. eapply (fsobj_disjoint H HH); [exact RF| exact FO| exact FF| exact B1| exact B2| exact B3| exact AP| left; lia].
  - intros POS. destruct VST as [[Z0 _]|(q & junk & INq & RBq & _)]; [exfalso; lia|].
    pose proof (rblock_bounds _ _ RBq) as (C1 & C2 & C3 & C4 & C5 & C6). pose proof RBq as (_ & _ & _ & APq & _).
    apply (disjoint_fsW5_retire H aceil aceil); [lia|]. eapply (fsobj_disjoint H HH); [exact RF| exact (FOV POS)| exact FF| exact C1| exact C2| exact C3| exact APq| left; lia].
  - apply (disjoint_fsW5_retire H aceil aceil); [lia|]. eapply (fsobj_disjoint_sh H HH); [exact RF| exact FO| exact FF| exact B1| exact B2| exact B3| lia].
  - intros POS. destruct VST as [[Z0 _]|(q & junk & INq & RBq & _)]; [exfalso; lia|].
    pose proof (rblock_bounds _ _ RBq) as (C1 & C2 & C3 & C4 & C5 & C6).
    apply (disjoint_fsW5_retire H aceil aceil); [lia|]. eapply (fsobj_disjoint_sh H HH); [exact RF| exact (FOV POS)| exact FF| exact C1| exact C2| exact C3| lia].
Qed.
