Lemma impl_storage_shm : forall LF ff fp m0 m1 m2 (LB : list block) implb vb (states : list Z) vcap lo sp,
  as_RFS H LF m0 -> fresh_frame H LF 1 ff fp -> aceil <= lo -> aapp implb SZ_SPCI_IMPL ->
  (0 < vcap -> vb + 8 * vcap <= implb \/ implb + SZ_SPCI_IMPL <= vb) -> (0 < vcap -> fsobj H LF vb (8 * vcap)) ->
  ((vcap = 0 /\ vb = 0)
   \/ (exists (q : bptr) junk, In (q, vb, 8 * vcap) LB /\ rblock_range vb (8 * vcap) /\ 0 < vcap
        /\ rw_cells bsegs m1 vb [CB (8 * length states) (flat_map le8z states); CB (Z.to_nat (8 * (vcap - zlength states))) junk]
        /\ SHAD m1 vb (cc_shadow (8 * vcap) (8 * zlength states)))) ->
  zlength states <= vcap -> munch (shm_W lo sp implb ff) m1 m2 -> wmono bsegs m1 m2 ->
  ((vcap = 0 /\ vb = 0)
   \/ (exists (q : bptr) junk, In (q, vb, 8 * vcap) LB /\ rblock_range vb (8 * vcap) /\ 0 < vcap
        /\ rw_cells bsegs m2 vb [CB (8 * length states) (flat_map le8z states); CB (Z.to_nat (8 * (vcap - zlength states))) junk]
        /\ SHAD m2 vb (cc_shadow (8 * vcap) (8 * zlength states)))).
