Lemma frame_v_accessible : forall m ff (z0 z1 z2 z3 z7 z8 z9 z10 z11 z12 z13 z14 z15 : byte),
  0 <= ff -> ff mod 8 = 0 -> ff + 56 <= AAPP_HI ->
  rw_cells bsegs m (Z.shiftr ff 3 + 2147450880)
    [C1 z0; C1 z1; C1 z2; C1 z3; C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 z7; C1 z8; C1 z9; C1 z10; C1 z11; C1 z12; C1 z13; C1 z14; C1 z15] ->
