Lemma sh_mid : forall (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (rax t0' t1' t2' a1' a2' a3' a4' a6' a7' t3' t4' t5' t6' : word)
    (v implb spa lo shi ff fp : Z) (LB : list block) (LF : list fframe) (S : svch) (I : implv)
    (m m2 : mem) (high : list cell) (j0 ja jb hj vj rj : list byte),
  lo + AINTRIN_STACK <= spa -> spa + 160 <= bv_unsigned sp -> spa mod 32 = 0 ->
  (* [comment removed for export] *)
  rw_cells bsegs m2 spa [CB 8 j0; C8 (Z_to_bv 64 ff); CB 24 ja; C8 (Z_to_bv 64 ff); CB 8 jb] ->
  rw_cells bsegs m2 (spa + 56) high -> Z.of_nat (cells_size high) = bv_unsigned sp + -160 - spa ->
  rw_cells bsegs m2 (bv_unsigned sp + -104) (sh_saved s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra) ->
  rw_cells bsegs m2 ff [CB 32 hj] -> rw_cells bsegs m2 (ff + 32) [CB 24 vj] -> rw_cells bsegs m2 (ff + 56) [CB 64 rj; C8 (Z_to_bv 64 fp)] ->
  rw_cells bsegs m2 (Z.shiftr ff 3 + 2147450880)
     [C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0);
      C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0); C1 (b8 0)] ->
  rw_cells bsegs m2 fp [C1 (b8 1)] ->
  stk bsegs m2 lo spa -> mem_inv bsegs m2 ->
  as_RFS H ((1, ff, fp) :: LF) m2 -> fresh_frame H LF 1 ff fp -> ACONST m2 -> stack0 m2 lo shi -> bv_unsigned sp + 64 <= shi ->
  as_RFS H LF m ->
  munch (sh_W H lo sp implb ff fp) m m2 -> wmono bsegs m m2 ->
  AStreamSvc LB m2 v S implb -> AImplBlockC LB m2 implb I -> im_lk I = 0 -> im_states I = [] ->
  (v + NEWSZ_SSVC <= implb \/ implb + SZ_SPCI_IMPL <= v) ->
  (0 < im_vcap I -> im_vb I + 8 * im_vcap I <= implb \/ implb + SZ_SPCI_IMPL <= im_vb I) ->
  fsobj H LF v NEWSZ_SSVC -> fsobj H LF implb SZ_SPCI_IMPL -> (0 < im_vcap I -> fsobj H LF (im_vb I) (8 * im_vcap I)) ->
  aceil <= lo -> bv_unsigned ra mod 2 = 0 ->
  evt bsegs (ssvc_shutdown_post H ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LB LF v implb lo shi S I m)
    (MS (mkR rax (Z_to_bv 64 spa) gp tp t0' t1' t2' sp (Z_to_bv 64 spa) (Z_to_bv 64 ff) a1' a2' a3' a4' (Z_to_bv 64 ff) a6' a7'
             s2 s3 (Z_to_bv 64 v) s5 s6 (Z_to_bv 64 2147450880) s8 s9 s10 s11 t3' t4' t5' t6')
        F (Z_to_bv 64 ASH_MID) fc None m2 (seg_rom bsegs)).
